mapper.update:

/*insertCommonCoCoBuyerCurrencyHist*/
		INSERT INTO KEP_CURRENCY_HIST
		(EXP_CODE
		,BUYER
		,BUYER_ITEM_NO
		,CONTRACT_NO
		,CONTRACT_SEQ
		,EXP_SEQ
		,STATUS
		,EXP_FOR_UNIT_PRICE
		,EXP_KR_UNIT_PRICE
		,EXP_INC_EXPENSE
		,ADD_USER_ID
		,ADD_DATE
		,ADD_TIME
		,CHANGE_USER_ID
		,CHANGE_DATE
		,CHANGE_TIME
		)
		VALUES
		(
			#{EXP_CODE}
			,#{st_buyer}
			,#{st_buyer_item_no}
			,#{st_contract_no}
			,#{st_contract_seq}
			,NVL((SELECT TO_NUMBER(MAX(A.EXP_SEQ)) 
				FROM KEP_CURRENCY_HIST A
				 WHERE A.EXP_CODE =#{EXP_CODE} 
				 AND A.BUYER =#{st_buyer}
				 AND A.CONTRACT_NO =#{st_contract_no}
				 AND A.CONTRACT_SEQ = #{st_contract_seq}),0)  +1
			,'C'
			,F_GET_EXCHANGE_RATE(#{st_below_code},#{st_unit_price},#{EXP_CODE},'01')
			,F_GET_EXCHANGE_RATE(#{st_below_code},#{st_unit_price},#{EXP_CODE},'03')
			,F_GET_EXCHANGE_RATE(#{st_below_code},#{st_unit_price},#{EXP_CODE},'02')
			,#{st_user_id}
			,TO_CHAR(SYSDATE, 'YYYYMMDD')
			,TO_CHAR(SYSDATE, 'HH24MISS')
			,#{st_user_id}
			,TO_CHAR(SYSDATE, 'YYYYMMDD')
			,TO_CHAR(SYSDATE, 'HH24MISS')
		)


/*"deleteCommonCoCoBuyerCurrency"*/
		DELETE KEP_CURRENCY_DT
		WHERE EXP_CODE = #{EXP_CODE}
		AND BUYER = #{BUYER} 
		AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}
		AND CONTRACT_NO = #{CONTRACT_NO}
		AND CONTRACT_SEQ = #{CONTRACT_SEQ}
